def transform(grid):
    h, w = len(grid), len(grid[0])

    # Complete a repeating sequence of uniform rows.
    row_colors = []
    horizontal = True
    for row in grid:
        colors = set(row) - {0}
        if len(colors) > 1:
            horizontal = False
            break
        row_colors.append(next(iter(colors)) if colors else None)
    if horizontal:
        for period in range(1, h + 1):
            pattern = {}
            for i, color in enumerate(row_colors):
                if color is not None:
                    residue = i % period
                    if residue in pattern and pattern[residue] != color:
                        break
                    pattern[residue] = color
            else:
                if len(pattern) == period:
                    colors = [pattern[i % period] for i in range(h)]
                    return [[colors[i]] * w for i in range(h)]

    # Otherwise complete the smallest fully specified periodic diagonal pattern.
    for diagonal in (lambda r, c: c - r, lambda r, c: r + c):
        for period in range(1, max(h, w) + 1):
            pattern = {}
            valid = True
            for r, row in enumerate(grid):
                for c, color in enumerate(row):
                    if color == 0:
                        continue
                    residue = diagonal(r, c) % period
                    if residue in pattern and pattern[residue] != color:
                        valid = False
                        break
                    pattern[residue] = color
                if not valid:
                    break
            if valid and len(pattern) == period:
                return [[pattern[diagonal(r, c) % period] for c in range(w)]
                        for r in range(h)]
    raise ValueError("No complete repeating pattern found")

